const std=@import("std");
fn fft(r:*[32]f64,im:*[32]f64,n:usize,inverse:bool) void {var j:usize=0;var i:usize=1;while(i<n):(i+=1){var bit=n>>1;while((j&bit)!=0){j^=bit;bit>>=1;}j^=bit;if(i<j){std.mem.swap(f64,&r[i],&r[j]);std.mem.swap(f64,&im[i],&im[j]);}}var len:usize=2;while(len<=n):(len*=2){const a=(if(inverse) @as(f64,1) else -1)*2*std.math.pi/@as(f64,@floatFromInt(len));const cr=@cos(a);const ci=@sin(a);var s:usize=0;while(s<n):(s+=len){var wr:f64=1;var wi:f64=0;var k:usize=0;while(k<len/2):(k+=1){const u=s+k;const v=u+len/2;const pr=wr*r[v]-wi*im[v];const ip=wr*im[v]+wi*r[v];const ur=r[u];const ui=im[u];r[u]=ur+pr;im[u]=ui+ip;r[v]=ur-pr;im[v]=ui-ip;const nr=wr*cr-wi*ci;wi=wr*ci+wi*cr;wr=nr;}}}if(inverse){i=0;while(i<n):(i+=1){r[i]/=@floatFromInt(n);im[i]/=@floatFromInt(n);}}}
fn quant(x:f64)i64{const z=x*1_000_000;if(z>=0)return @intFromFloat(z+0.5);return @intFromFloat(z-0.5);}
fn store(o:[*]u8,p:usize,x:i64)void{const b=@as(u64,@bitCast(x));var i:usize=0;while(i<8):(i+=1)o[p+i]=@truncate(b>>@intCast(i*8));}
export fn fft_bluestein(v:?[*]const i64,n:usize,out:?[*]u8,cap:usize)i64{if(v==null or n < 2 or n > 9)return -1;const a=v.?;const m=a[0];if(m < 1 or m > 8 or n!=@as(usize,@intCast(m))+1)return -1;for(0..@intCast(m))|i|{if(a[i+1] < -8 or a[i+1] > 8)return -1;}var z:usize=1;const need:usize=@intCast(3*m-2);while(z < need)z*=2;const bytes:usize=@intCast(m*16);if(out==null or cap < bytes)return -2;const output=out.?;var ar:[32]f64=@splat(0);var ai:[32]f64=@splat(0);var br:[32]f64=@splat(0);var bi:[32]f64=@splat(0);const mm:usize=@intCast(m);for(0..mm)|j|{const x=-std.math.pi*@as(f64,@floatFromInt(j*j))/@as(f64,@floatFromInt(mm));ar[j]=@as(f64,@floatFromInt(a[j+1]))*@cos(x);ai[j]=@as(f64,@floatFromInt(a[j+1]))*@sin(x);}var kk:isize=-@as(isize,@intCast(mm-1));while(kk<=@as(isize,@intCast(mm-1))):(kk+=1){const x=std.math.pi*@as(f64,@floatFromInt(kk*kk))/@as(f64,@floatFromInt(mm));const ix:usize=@intCast(kk+@as(isize,@intCast(mm-1)));br[ix]=@cos(x);bi[ix]=@sin(x);}fft(&ar,&ai,z,false);fft(&br,&bi,z,false);for(0..z)|i|{const x=ar[i]*br[i]-ai[i]*bi[i];ai[i]=ar[i]*bi[i]+ai[i]*br[i];ar[i]=x;}fft(&ar,&ai,z,true);for(0..mm)|k|{const x=-std.math.pi*@as(f64,@floatFromInt(k*k))/@as(f64,@floatFromInt(mm));const cr=@cos(x);const ci=@sin(x);const re=ar[k+mm-1]*cr-ai[k+mm-1]*ci;const im=ar[k+mm-1]*ci+ai[k+mm-1]*cr;store(output,16*k,quant(re));store(output,16*k+8,quant(im));}return @intCast(bytes);}
